import index from "./asset-index.generated.json";

// Only approved assets from assets/manifest.json reach the app (CR-7, CR-10). The index is
// generated by scripts/build-assets.ts; an id missing here is a build-time type error.
export type AssetId = keyof typeof index;

type Entry = { src: Record<string, string>; width: number; height: number; transparent: boolean };

export function asset(id: AssetId) {
  const e = (index as Record<string, Entry>)[id];
  const widths = Object.keys(e.src).map(Number).sort((a, b) => a - b);
  return {
    src: e.src[String(widths[Math.min(1, widths.length - 1)])],
    srcSet: widths.map((w) => `${e.src[String(w)]} ${w}w`).join(", "),
    width: e.width,
    height: e.height,
  };
}
